import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/document-style-guide/camelcase.html","title":"09-骆驼拼写法（CamelCase）","lang":"zh-CN","frontmatter":{"title":"09-骆驼拼写法（CamelCase）","date":"2023-01-26T08:52:57.000Z","author":"AI悦创","isOriginal":true,"category":["中文技术文档的写作规范"],"tag":["中文技术文档的写作规范"],"icon":"docs","sticky":false,"star":false,"article":true,"timeline":true,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"imgimg 注解 在英语中，依靠单词的大小写拼写复合词的做法，叫做&quot;骆驼拼写法&quot;（CamelCase）。比如，backColor 这个复合词，color 的第一个字母采用大写。 这种拼写法在正规的英语中是不允许的，但是在编程语言和商业活动中却大量使用。比如，sony 公司的畅销游戏机 PlayStation，play 和 stat...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"09-骆驼拼写法（CamelCase）\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2023-01-26T08:52:57.000Z\\",\\"dateModified\\":\\"2025-04-10T23:49:50.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/document-style-guide/camelcase.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"09-骆驼拼写法（CamelCase）"}],["meta",{"property":"og:description","content":"imgimg 注解 在英语中，依靠单词的大小写拼写复合词的做法，叫做&quot;骆驼拼写法&quot;（CamelCase）。比如，backColor 这个复合词，color 的第一个字母采用大写。 这种拼写法在正规的英语中是不允许的，但是在编程语言和商业活动中却大量使用。比如，sony 公司的畅销游戏机 PlayStation，play 和 stat..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-04-10T23:49:50.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:tag","content":"中文技术文档的写作规范"}],["meta",{"property":"article:published_time","content":"2023-01-26T08:52:57.000Z"}],["meta",{"property":"article:modified_time","content":"2025-04-10T23:49:50.000Z"}]]},"git":{"createdTime":1674695252000,"updatedTime":1744328990000,"contributors":[{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":2},{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":1,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"c9a1efeadfb95dc4436e9f28df9ee881f36992ab","time":1674695252000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"}]},"readingTime":{"minutes":2.47,"words":742},"filePathRelative":"column/document-style-guide/camelcase.md","excerpt":"<figure><figcaption>img</figcaption></figure>\\n<div class=\\"hint-container info\\">\\n<p class=\\"hint-container-title\\">注解</p>\\n<p>在英语中，依靠单词的大小写拼写复合词的做法，叫做&quot;骆驼拼写法&quot;（CamelCase）。比如，backColor 这个复合词，color 的第一个字母采用大写。</p>\\n<p>这种拼写法在正规的英语中是不允许的，但是在编程语言和商业活动中却大量使用。比如，sony 公司的畅销游戏机 PlayStation，play 和 station 两个词的词首字母都是大写的。</p>\\n</div>","autoDesc":true}`),a={name:`camelcase.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/bg2007061201-BzkDhZJB.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><div class="hint-container info"><p class="hint-container-title">注解</p><p>在英语中，依靠单词的大小写拼写复合词的做法，叫做&quot;骆驼拼写法&quot;（CamelCase）。比如，backColor 这个复合词，color 的第一个字母采用大写。</p><p>这种拼写法在正规的英语中是不允许的，但是在编程语言和商业活动中却大量使用。比如，sony 公司的畅销游戏机 PlayStation，play 和 station 两个词的词首字母都是大写的。</p></div><p>它之所以被叫做&quot;骆驼拼写法&quot;，是因为大小写的区分使得复合词呈现&quot;块状&quot;（bump），看上去就像骆驼的驼峰（hump）。</p><p>&quot;骆驼拼写法&quot;又分为两种。第一个词的首字母小写，后面每个词的首字母大写，叫做&quot;小骆驼拼写法&quot;（lowerCamelCase）；第一个词的首字母，以及后面每个词的首字母都大写，叫做&quot;大骆驼拼写法&quot;（UpperCamelCase），又称&quot;帕斯卡拼写法&quot;（PascalCase）。</p><p>在历史上，&quot;骆驼拼写法&quot;早就存在。苏格兰人的姓名中的 Mac 前缀就是一例，比如著名歌手 Paul MacCartney 的名字中，M 和 C 都是大写的，如果将 C 小写就是错误的。另一个例子是，著名化学品公司杜邦公司的名字 DuPont。</p><p>但是，这种拼写法真正流行，还是在 80 年代以后，那时正是计算机语言开始兴起的时候。许多著名的计算机语言依靠单词不同的大小写来区分变量。在计算机语言中，还有一种&quot;匈牙利拼写法&quot;（Hungarian Type Notation），变量中每个单词的首字母都大写，然后变量名的最前面再加一个小写字母，表示这个单词的数据类型。比如，iMyTestValue 这个变量名，就表示它是一个整数变量（integer）。据说，微软公司最喜欢使用&quot;匈牙利拼写法&quot;。</p><p>（完）</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Linux、Web」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,10)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};